const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Elephant Butte Reservoir location
  const reservoir = ee.Geometry.Point([-107.18, 32.28]);
  const bufferZone = reservoir.buffer(15000); // 15km buffer for water body

  // Date ranges for comparison
  const date1Start = '1986-06-02';
  const date1End = '1986-06-22';
  const date2Start = '2020-05-30';
  const date2End = '2020-06-19';

  // 1986 - Landsat 5
  let col1986 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(bufferZone)
    .filterDate(date1Start, date1End)
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  let size1986 = col1986.size().getInfo();
  console.log(`1986 Images found: ${size1986}`);

  if (size1986 === 0) {
    console.log("No data for 1986.");
    console.log("C1");
    return;
  }

  // 2020 - Landsat 8
  let col2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(bufferZone)
    .filterDate(date2Start, date2End)
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  let size2020 = col2020.size().getInfo();
  console.log(`2020 Images found: ${size2020}`);

  if (size2020 === 0) {
    console.log("No data for 2020.");
    console.log("C1");
    return;
  }

  // Function to calculate water extent using NDWI
  function calcWaterExtent(col, isSR) {
    let img = col.median();

    let ndwi;
    if (isSR) {
      // Landsat 5: SR_B2=Green, SR_B4=NIR
      ndwi = img.normalizedDifference(['SR_B2', 'SR_B4']).rename('NDWI');
    } else {
      // Landsat 8: SR_B3=Green, SR_B5=NIR
      ndwi = img.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
    }

    // Water threshold: NDWI > 0.3
    let waterMask = ndwi.gt(0.3);
    let waterExtent = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: bufferZone,
      scale: 30,
      maxPixels: 1e9
    });

    return waterExtent.get('NDWI');
  }

  // Calculate water extent for both dates
  let water1986 = calcWaterExtent(col1986, true);
  let water2020 = calcWaterExtent(col2020, false);

  water1986 = water1986.getInfo();
  water2020 = water2020.getInfo();

  console.log(`1986 Water pixels: ${water1986}`);
  console.log(`2020 Water pixels: ${water2020}`);

  // Validate results
  if (water1986 === null || water1986 === 0) {
    console.log("No valid water pixels detected in 1986.");
    console.log("C2");
    return;
  }

  if (water2020 === null || water2020 === 0) {
    console.log("No valid water pixels detected in 2020.");
    console.log("C2");
    return;
  }

  // Compare water extents
  console.log(`1986 Water extent: ${water1986} pixels`);
  console.log(`2020 Water extent: ${water2020} pixels`);

  let change = water2020 - water1986;
  let percentChange = (change / water1986) * 100;
  console.log(`Change: ${change} pixels (${percentChange.toFixed(2)}%)`);

  // Determine answer
  if (water2020 < water1986) {
    console.log("Water extent DECREASED");
    console.log("A");
  } else {
    console.log("Water extent did NOT decrease");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
